func splitReviewVerdictFindings(verdict string) []string {
	var findings []string
	var current strings.Builder
	flush := func() {
		item := strings.TrimSpace(current.String())
		current.Reset()
		if item != "" {
			findings = append(findings, item)
		}
	}
	for _, line := range strings.Split(strings.TrimSpace(verdict), "\n") {
		if item, ok := cliReview.TopLevelBulletText(line); ok {
			flush()
			current.WriteString(item)
			continue
		}
		if item, ok := cliReview.TopLevelMarkedFindingText(line); ok {
			flush()
			current.WriteString(item)
			continue
		}
		if current.Len() == 0 {
			continue
		}
		current.WriteByte('\n')
		current.WriteString(line)
	}
	flush()
	return findings
}

